let rec dp (lst : List Int) : Nat :=
  match lst with
  | [] => 0
  | h :: t =>
    let end_pos : Option Int :=
      if h > last_of_list t then some h
      else none
    let len : Nat :=
      if end_pos.get! = none then 0
      else 1 + dp (t.map (fun x => if x < h then x else x))
    max len (dp lst)

