-- Kadane's Algorithm
let (cur, maxSoFar) :=
  sequence.foldl (fun (cur, maxSoFar) (x : Int) =>
    let newCur := if x + cur > cur then x + cur else cur
    let newMax := if maxSoFar >= newCur then maxSoFar else newCur
    (newCur, newMax)
  ) (0, 0)
let (newCur, newMax) := (cur, maxSoFar)
let result := if x + cur > cur then x + cur else cur
if maxSoFar >= result then maxSoFar else result

