  insertionSortHelper xs

def insertionSortHelper (xs : List Int) : List Int :=
  let rec aux (xs' : List Int) (acc : List Int) : List Int :=
    match xs' with
    | [] => acc.reverse
    | h :: t =>
      if h <! acc.head? then h :: aux t acc else acc.reverse
    aux xs []
  aux xs []

